targets.expr:
max(
  (
    1 - backup_nas_mount_up
  )
  or
  (
    (time() - backup_collector_last_success_timestamp_seconds > bool 2700)
  )
  or
  (
    1 - backup_present{target="local",service=~"homeassistant|paperless|monitoring"}
  )
  or
  (
    1 - backup_present{target="nas",service=~"homeassistant|paperless|monitoring"}
  )
  or
  (
    1 - backup_present{target="onedrive",service=~"homeassistant|paperless|monitoring|traefik|sentinel|vps-dr"}
  )
  or
  (
    1 - backup_cloud_query_success{service=~"homeassistant|paperless|monitoring|traefik|sentinel|vps-dr"}
  )
  or
  (
    1 - backup_all_targets_match{service=~"homeassistant|paperless|monitoring"}
  )
  or
  (
    (
      time() - backup_last_timestamp_seconds{
        target="onedrive",
        service=~"homeassistant|paperless|monitoring|traefik|sentinel|vps-dr"
      }
    ) > bool 129600
  )
)

(
  time() -
  backup_last_timestamp_seconds{
    service="traefik",
    target="onedrive"
  }
)
and
(
  backup_present{service="traefik",target="onedrive"} == 1
)
and
(
  backup_cloud_query_success{service="traefik"} == 1
)

(
  time() -
  backup_last_timestamp_seconds{
    service="sentinel",
    target="onedrive"
  }
)
and
(
  backup_present{service="sentinel",target="onedrive"} == 1
)
and
(
  backup_cloud_query_success{service="sentinel"} == 1
)

(
  time() -
  backup_last_timestamp_seconds{
    service="vps-dr",
    target="onedrive"
  }
)
and
(
  backup_present{service="vps-dr",target="onedrive"} == 1
)
and
(
  backup_cloud_query_success{service="vps-dr"} == 1
)
